import json
from itertools import permutations

langs = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": {"Korean", "French", "English", "German"},
}
names = list(langs)

def comm(a, b):
    return bool(langs[a] & langs[b])

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

sols = []
for p in permutations(names):
    pos = {n: i for i, n in enumerate(p)}

    def nbrs(n):
        i = pos[n]
        return [p[j] for j in (i - 1, i + 1) if 0 <= j < 4]

    if not pos["South Korea"] > pos["Germany"]:
        continue
    if any(comm("South Korea", x) for x in nbrs("South Korea")):
        continue
    if any(comm("France", x) for x in nbrs("France")):
        continue
    if sum(comm("Britain", x) for x in nbrs("Britain")) != 1:
        continue
    sols.append(p)

matches = [k for k, v in options.items() if tuple(v) in [tuple(s) for s in sols]]

if len(sols) == 1 and len(matches) == 1:
    ans = f"{matches[0]}. " + ", ".join(sols[0])
    print(json.dumps({"final_answer": ans,
                      "evidence": {"solutions": [list(s) for s in sols],
                                   "matching_options": matches}}))
else:
    print("UNSUPPORTED")
